import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"第 15 课：课程回顾与学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-6/lesson-15.md","filePath":"modules/module-6/lesson-15.md"}'),l={name:"modules/module-6/lesson-15.md"};function o(h,t,i,n,s,b){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-15-课-课程回顾与学习路径" tabindex="-1">第 15 课：课程回顾与学习路径 <a class="header-anchor" href="#第-15-课-课程回顾与学习路径" aria-label="Permalink to &quot;第 15 课：课程回顾与学习路径&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：回顾核心知识点，掌握常见问题排查方法<br> ⏱️ <strong>预计时长</strong>：15 分钟<br> 🎯 <strong>本节节奏</strong>：总结回顾 + 问题排查</p></blockquote><hr><h2 id="一、核心知识点回顾" tabindex="-1">一、核心知识点回顾 <a class="header-anchor" href="#一、核心知识点回顾" aria-label="Permalink to &quot;一、核心知识点回顾&quot;">​</a></h2><h3 id="模块一-认识-codex" tabindex="-1">模块一：认识 Codex <a class="header-anchor" href="#模块一-认识-codex" aria-label="Permalink to &quot;模块一：认识 Codex&quot;">​</a></h3><ul><li>Codex 是 OpenAI 的 AI 编程智能体，能读文件、写代码、运行命令</li><li>它不是聊天工具，也不是简单的代码补全工具</li><li>类比理解：Codex = 会编程的实习生</li></ul><h3 id="模块二-上手准备" tabindex="-1">模块二：上手准备 <a class="header-anchor" href="#模块二-上手准备" aria-label="Permalink to &quot;模块二：上手准备&quot;">​</a></h3><ul><li>需要 ChatGPT 账号（推荐 Plus/Pro）</li><li>桌面 App 是最适合新手的入口</li><li>核心概念：工作区（Workspace）和权限模式</li></ul><h3 id="模块三-核心功能" tabindex="-1">模块三：核心功能 <a class="header-anchor" href="#模块三-核心功能" aria-label="Permalink to &quot;模块三：核心功能&quot;">​</a></h3><ul><li>文件操作：读取、编辑、整理、批量处理</li><li>自然语言驱动：用说话来指挥 AI</li><li>联网检索：搜索 + 整理 + 总结</li><li>自动化：批量重命名、下载整理、脚本编写</li></ul><h3 id="模块四-实用技巧" tabindex="-1">模块四：实用技巧 <a class="header-anchor" href="#模块四-实用技巧" aria-label="Permalink to &quot;模块四：实用技巧&quot;">​</a></h3><ul><li>写好指令的四要素：动作 + 对象 + 规则 + 验收标准</li><li>安全使用：备份重要文件、限制工作区</li><li>技能调用：PPT 生成、网页开发等预置模板</li></ul><h3 id="模块五-项目实战" tabindex="-1">模块五：项目实战 <a class="header-anchor" href="#模块五-项目实战" aria-label="Permalink to &quot;模块五：项目实战&quot;">​</a></h3><ul><li>项目一：整理电脑文件夹</li><li>项目二：生成 PPT 报告</li><li>项目三：创建个人简介网页</li><li>项目四：待办事项管理小工具</li></ul><hr><h2 id="二、常见问题排查" tabindex="-1">二、常见问题排查 <a class="header-anchor" href="#二、常见问题排查" aria-label="Permalink to &quot;二、常见问题排查&quot;">​</a></h2><h3 id="问题-1-登录失败" tabindex="-1">问题 1：登录失败 <a class="header-anchor" href="#问题-1-登录失败" aria-label="Permalink to &quot;问题 1：登录失败&quot;">​</a></h3><table tabindex="0"><thead><tr><th>可能原因</th><th>解决方案</th></tr></thead><tbody><tr><td>网络不稳定</td><td>检查网络连接，尝试切换网络</td></tr><tr><td>账号未激活</td><td>确认邮箱已验证</td></tr><tr><td>地区限制</td><td>确认你的地区是否支持 Codex</td></tr></tbody></table><h3 id="问题-2-权限问题" tabindex="-1">问题 2：权限问题 <a class="header-anchor" href="#问题-2-权限问题" aria-label="Permalink to &quot;问题 2：权限问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>解决方案</th></tr></thead><tbody><tr><td>Codex 无法访问文件夹</td><td>检查工作区设置是否正确</td></tr><tr><td>操作被拒绝</td><td>检查权限模式设置</td></tr><tr><td>文件无法保存</td><td>确认文件夹有写入权限</td></tr></tbody></table><h3 id="问题-3-任务卡住" tabindex="-1">问题 3：任务卡住 <a class="header-anchor" href="#问题-3-任务卡住" aria-label="Permalink to &quot;问题 3：任务卡住&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>解决方案</th></tr></thead><tbody><tr><td>Codex 长时间无响应</td><td>刷新页面或重启应用</td></tr><tr><td>输出不符合预期</td><td>重新描述需求，更具体一些</td></tr><tr><td>报错信息看不懂</td><td>把错误信息复制给 Codex 让它解释</td></tr></tbody></table><h3 id="问题-4-额度不足" tabindex="-1">问题 4：额度不足 <a class="header-anchor" href="#问题-4-额度不足" aria-label="Permalink to &quot;问题 4：额度不足&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>解决方案</th></tr></thead><tbody><tr><td>提示额度用完</td><td>升级到 Plus 或 Pro</td></tr><tr><td>免费额度不够用</td><td>等待下月重置或使用其他工具</td></tr></tbody></table><hr><h2 id="三、推荐学习资源" tabindex="-1">三、推荐学习资源 <a class="header-anchor" href="#三、推荐学习资源" aria-label="Permalink to &quot;三、推荐学习资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源类型</th><th>链接/名称</th><th>说明</th></tr></thead><tbody><tr><td>官方文档</td><td>chatgpt.com/docs</td><td>OpenAI 官方文档</td></tr><tr><td>社区论坛</td><td>community.openai.com</td><td>用户交流和经验分享</td></tr><tr><td>YouTube 教程</td><td>搜索&quot;Codex tutorial&quot;</td><td>视频教程</td></tr><tr><td>Reddit 社区</td><td>r/Claude, r/OpenAI</td><td>讨论最新进展</td></tr></tbody></table><hr><h2 id="四、本节小结" tabindex="-1">四、本节小结 <a class="header-anchor" href="#四、本节小结" aria-label="Permalink to &quot;四、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>知识回顾</td><td>从安装到实战的完整学习路径</td></tr><tr><td>问题排查</td><td>登录、权限、任务卡住、额度等问题</td></tr><tr><td>学习资源</td><td>官方文档、社区、视频教程</td></tr></tbody></table><hr><h2 id="五、下一步" tabindex="-1">五、下一步 <a class="header-anchor" href="#五、下一步" aria-label="Permalink to &quot;五、下一步&quot;">​</a></h2><p><a href="./lesson-16.html">→ 第 16 课：下一步可以学什么</a></p>',33)])])}const m=a(l,[["render",o]]);export{c as __pageData,m as default};
